#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/android/tasks/test-golden-android.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Verify the Android screens against their golden images with Roborazzi or Paparazzi; --record records them again"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--record" help="record every golden again instead of verifying against them"

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def exit_code(code):
  """The exit code of the shell for a return code of subprocess."""
  return code if code >= 0 else 128 - code


def contains(files, text):
  """Whether one of the files contains the bytes text. A file that cannot be
  read does not count."""
  for file in files:
    try:
      with open(file, "rb") as data:
        if text in data.read():
          return True
    except OSError:
      continue
  return False


def main():
  os.chdir(os.environ["MISE_PROJECT_ROOT"])

  # Shipped with the android tool. It acts on the Gradle build at the root
  # only: the android/ folder of a Flutter app is for the flutter tool. Its one
  # flag is --record, because test:golden passes the same arguments to each
  # part. It reads this value, with a default; a repository sets it in the
  # [env] of .config/mise/conf.d/zz-repo/mise.<env>.toml:
  #   ANDROID_VARIANT  the build variant whose unit tests hold the goldens
  #                    (debug)
  #
  # The library comes from the plugin ids in settings.gradle(.kts), each
  # build.gradle(.kts) and gradle/libs.versions.toml: Roborazzi
  # (io.github.takahirom.roborazzi), Paparazzi (app.cash.paparazzi), or both.
  # Without either id or without an executable ./gradlew, the part does not
  # apply and prints nothing.
  if not os.access("gradlew", os.X_OK):
    sys.exit(0)
  # A failed git stops the task, with the error of git.
  result = subprocess.run(
    [
      "git",
      "-c",
      "core.quotePath=off",
      "ls-files",
      "--cached",
      "--others",
      "--exclude-standard",
      "--",
      "settings.gradle",
      "settings.gradle.kts",
      "build.gradle",
      "build.gradle.kts",
      "*/build.gradle",
      "*/build.gradle.kts",
      "gradle/libs.versions.toml",
    ],
    check=False,
    stdout=subprocess.PIPE,
  )
  if result.returncode != 0:
    sys.exit(exit_code(result.returncode))
  files = [file for file in os.fsdecode(result.stdout).split("\n") if file and os.path.isfile(file)]
  if not files:
    sys.exit(0)

  roborazzi = contains(files, b"io.github.takahirom.roborazzi")
  paparazzi = contains(files, b"app.cash.paparazzi")
  if not roborazzi and not paparazzi:
    sys.exit(0)

  variant = os.environ.get("ANDROID_VARIANT") or "debug"
  variant_name = variant[:1].upper() + variant[1:]

  mode = "record" if os.environ.get("usage_record", "false") == "true" else "verify"
  tasks = []
  if roborazzi:
    tasks.append(f"{mode}Roborazzi{variant_name}")
  if paparazzi:
    tasks.append(f"{mode}Paparazzi{variant_name}")

  if mode == "record":
    helpers.print_header(f"Recording the Android goldens ({variant_name}) ...")
  else:
    # Verify fails on a changed render and on a screen with no golden.
    helpers.print_header(f"Verifying the Android goldens ({variant_name}) ...")
  result = subprocess.run(["./gradlew", *tasks], check=False)
  sys.exit(exit_code(result.returncode))


main()
